// FB Posts: Normalize + Claude Parse
const HUB = 'https://ap-home-platform.vercel.app/api/chat';
const body = $input.first().json.body ?? $input.first().json;

const raw_text = body.post_text ?? body.text ?? '';
const area_hint = body.area ?? null;
const post_date = body.post_date ?? new Date().toISOString().split('T')[0];

const SYSTEM = `คุณเป็น Market Intelligence Parser สำหรับ Finnhouses อสังหาริมทรัพย์ไทย
วิเคราะห์โพสต์ขายบ้าน → ส่งออก JSON เท่านั้น ไม่มีข้อความอื่น

JSON format:
{
  "area": "ชื่อพื้นที่ภาษาไทย",
  "insight": "ข้อสังเกตสำคัญ 1 ประโยค",
  "category": "risk_perception|demand_pattern|liquidity_signal|price_behavior|competitor_gap",
  "confidence": 1,
  "property_type": "ทาวน์เฮ้าส์|บ้านเดี่ยว|ที่ดิน|คอนโด",
  "price": number_or_null,
  "urgency": true,
  "buyer_segment": "resale|build_handsoff|build_handson",
  "timing_signal": "none|bonus|rate_up|rainy|new_year|marriage|land_ready",
  "emotional_keywords": ["array"],
  "positioned_hook": "hook ≤ 40 คำ"
}`;

const PROMPT = `Source: fb\nArea hint: ${area_hint ?? 'ไม่ระบุ'}\nText: ${raw_text.slice(0, 800)}\n\nส่งออก JSON เท่านั้น`;

let parsed = {};
try {
  const res = await this.helpers.request({
    method: 'POST',
    url: HUB,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'claude-haiku-4-5-20251001', maxTokens: 600, system: SYSTEM, prompt: PROMPT }),
    json: false,
  });
  const data = JSON.parse(res);
  const match = (data.text ?? '').match(/\{[\s\S]*\}/);
  if (match) parsed = JSON.parse(match[0]);
} catch(e) { parsed.error = e.message; }

return [{ json: {
  source: 'fb',
  source_type: 'social',
  raw_text,
  area_hint,
  post_date,
  seller_id: body.seller_id ?? null,
  ...parsed,
  area: parsed.area ?? area_hint ?? 'unknown',
  parse_ok: !!(parsed.area && parsed.insight && !parsed.error),
}}];

// Manual Input: Normalize + Claude Parse
const HUB = 'https://ap-home-platform.vercel.app/api/chat';
const body = $input.first().json.body ?? $input.first().json;

const raw_text = body.text ?? body.observation ?? '';
const area_hint = body.area ?? null;
const post_date = new Date().toISOString().split('T')[0];

const SYSTEM = `คุณเป็น Market Intelligence Parser สำหรับ Finnhouses อสังหาริมทรัพย์ไทย
วิเคราะห์การสังเกตการณ์ตลาดจากมนุษย์ → ส่งออก JSON เท่านั้น ไม่มีข้อความอื่น

JSON format:
{
  "area": "ชื่อพื้นที่ภาษาไทย",
  "insight": "ข้อสังเกตสำคัญ 1 ประโยค",
  "category": "risk_perception|demand_pattern|liquidity_signal|price_behavior|competitor_gap",
  "confidence": 4,
  "property_type": "ทาวน์เฮ้าส์|บ้านเดี่ยว|ที่ดิน|คอนโด|null",
  "price": number_or_null,
  "urgency": false,
  "buyer_segment": "resale|build_handsoff|build_handson",
  "timing_signal": "none|bonus|rate_up|rainy|new_year|marriage|land_ready",
  "emotional_keywords": [],
  "positioned_hook": "hook ≤ 40 คำ"
}`;

const PROMPT = `Source: manual observation\nArea hint: ${area_hint ?? 'ไม่ระบุ'}\nText: ${raw_text.slice(0, 800)}\n\nส่งออก JSON เท่านั้น`;

let parsed = {};
try {
  const res = await this.helpers.request({
    method: 'POST',
    url: HUB,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'claude-haiku-4-5-20251001', maxTokens: 600, system: SYSTEM, prompt: PROMPT }),
    json: false,
  });
  const data = JSON.parse(res);
  const match = (data.text ?? '').match(/\{[\s\S]*\}/);
  if (match) parsed = JSON.parse(match[0]);
} catch(e) { parsed.error = e.message; }

return [{ json: {
  source: 'manual',
  source_type: 'observation',
  raw_text,
  area_hint,
  post_date,
  seller_id: null,
  ...parsed,
  area: parsed.area ?? area_hint ?? 'unknown',
  parse_ok: !!(parsed.area && parsed.insight && !parsed.error),
}}];

// Insert market_insights to Supabase
// FIXED: ใช้ getCredentials() แทน $env
const d = $input.first().json;
const creds = await this.getCredentials('supabaseApi');
const SUPABASE_KEY = creds.serviceRole;
const SUPABASE_URL = 'https://omvpagvqyfmkkhzuuzda.supabase.co/rest/v1/market_insights';

try {
  await this.helpers.request({
    method: 'POST',
    url: SUPABASE_URL,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': 'Bearer ' + SUPABASE_KEY,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal',
    },
    body: JSON.stringify({
      area: d.area,
      insight: d.insight,
      category: d.category ?? 'demand_pattern',
      confidence: d.confidence ?? 3,
      source_type: d.source_type ?? 'manual',
      notes: (d.raw_text ?? '').slice(0, 500),
    }),
    json: false,
  });
} catch(e) {
  console.log('market_insights insert error:', e.message);
}

return [{ json: { ...d, market_insight_saved: true } }];

// บันทึก buyer_context_signals ถ้ามี timing_signal
// FIXED: ใช้ getCredentials() แทน $env
const d = $input.first().json;
const creds = await this.getCredentials('supabaseApi');
const SUPABASE_KEY = creds.serviceRole;

if (!d.timing_signal || d.timing_signal === 'none') {
  // ไม่มี timing signal — ข้ามขั้นตอนนี้
  return [{ json: { ...d, buyer_context_saved: false } }];
}

try {
  await this.helpers.request({
    method: 'POST',
    url: 'https://omvpagvqyfmkkhzuuzda.supabase.co/rest/v1/buyer_context_signals',
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': 'Bearer ' + SUPABASE_KEY,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal',
    },
    body: JSON.stringify({
      trigger_type: d.timing_signal,
      awareness_level: 'problem_aware',
      emotional_need: d.category === 'risk_perception' ? 'ความปลอดภัย' : 'ความภาคภูมิใจ',
      content_angle: d.positioned_hook ?? d.insight ?? '',
      channel: 'facebook',
      example_hook: d.positioned_hook ?? '',
    }),
    json: false,
  });
} catch(e) {
  // silent fail — ไม่หยุด flow หลัก
  console.log('buyer_context insert error:', e.message);
}

return [{ json: { ...d, buyer_context_saved: true } }];

// Save positioned content to content_frames table
// FIXED: ใช้ getCredentials() แทน $env
const d = $input.first().json;
const ctx = $('💾 buyer_context (conditional)').first().json;
const creds = await this.getCredentials('supabaseApi');
const SUPABASE_KEY = creds.serviceRole;

try {
  await this.helpers.request({
    method: 'POST',
    url: 'https://omvpagvqyfmkkhzuuzda.supabase.co/rest/v1/content_frames',
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': 'Bearer ' + SUPABASE_KEY,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal',
    },
    body: JSON.stringify({
      area:           ctx.area ?? 'unknown',
      target_segment: ctx.buyer_segment ?? 'general',
      keyword:        ctx.positioned_hook ?? ctx.insight ?? '',
      frame_text:     d.text ?? '',
      timing_signal:  ctx.timing_signal ?? 'none',
      source_type:    ctx.source_type ?? 'manual',
    }),
    json: false,
  });
} catch(e) {
  console.log('content_frames insert error:', e.message);
}

return [{ json: { ...d, content_frame_saved: true } }];

